let mapa: Map<string, string> | null = null;

function carregar(): Map<string, string> {
  const m = new Map<string, string>();
  for (const linha of TABELA.split('\n')) {
    if (linha[2] !== ':') continue;
    const uf = linha.slice(0, 2);
    for (const item of linha.slice(3).split('|')) {
      m.set(uf + item.slice(0, 5), item.slice(5));
    }
  }
  return m;
}

/** Nome do município pelo código IBGE de 7 dígitos, ou '' fora da tabela. */
export function nomeMunicipioIbge(codigo: string): string {
  const c = codigo.trim();
  if (!/^\d{7}$/.test(c)) return '';
  mapa ??= carregar();
  return mapa.get(c) ?? '';
}

/** Quantos municípios a tabela tem. */
export function totalMunicipiosIbge(): number {
  mapa ??= carregar();
  return mapa.size;
}
